// Common: helpers shared by every module: a SplitMix64 generator, rotation and FNV-1a mixing.
// Generated by `dotnet run --project Runner -c Release -- generate`; change the generator, not this file.
#pragma once

#include <bit>
#include <cstdint>

namespace common {

class Rng {
public:
    explicit Rng(uint64_t seed) : state_(seed) {}

    uint64_t next() {
        state_ += 0x9E3779B97F4A7C15ULL;
        uint64_t z = state_;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
        return z ^ (z >> 31);
    }

private:
    uint64_t state_;
};

inline uint64_t rotl(uint64_t value, int amount) {
    return std::rotl(value, amount);
}

inline uint64_t fnv(uint64_t hash, uint64_t value) {
    return (hash ^ value) * 0x100000001B3ULL;
}

}  // namespace common
